import { useEffect, useRef } from 'react'

type IntervalHookOptions = {
  interval: number
  callback: (timestamp: number) => void
}

export function useInterval({ interval, callback }: IntervalHookOptions) {
  const savedCallback = useRef<(timestamp: number) => void>()

  useEffect(() => {
    savedCallback.current = callback
  }, [callback])

  useEffect(() => {
    function tick() {
      if (savedCallback.current) {
        savedCallback.current(Date.now())
      }
    }

    if (interval > 0) {
      const timerId = setInterval(tick, interval)
      return () => clearInterval(timerId)
    }
  }, [interval])
}
